#!/usr/bin/env python3
"""Packs the encoded reference voices into NeuralSpeech's MossVoiceLibrary.swift (generated, do not edit by hand).

  build_library.py <workdir containing json/>
"""
import base64, json, os, struct, sys

work = sys.argv[1]
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "Packages", "NeuralSpeech", "Sources", "NeuralSpeech", "Moss", "MossVoiceLibrary.swift")
# source id -> (app id, display name, note, gender)
VOICES = [
    ("xiaoqing", "moss-yunshu", "云舒", "明亮、自然、有笑意", "female"),
    ("xiaoya", "moss-shuyao", "书瑶", "温和、清晰、亲切", "female"),
    ("laofu", "moss-laofu", "老傅", "成熟、沉稳、娓娓道来", "male"),
    ("dylan", "moss-ajing", "阿京", "年轻、轻松、带京腔", "male"),
]
STYLES = ["neutral", "cheerful", "calm"]

def pack(codes):
    flat = [v for frame in codes for v in frame]
    assert all(0 <= v < 1024 for v in flat) and len(flat) % 16 == 0
    return base64.b64encode(struct.pack("<%dh" % len(flat), *flat)).decode()

lines = ["// Generated by tools/voices/build_library.py from Qwen3-TTS CustomVoice reference recordings (Apache-2.0) encoded with the",
         "// MOSS codec. Do not edit by hand. Each reference is base64 of little-endian Int16 codes, 16 per 80 ms frame.",
         "", "public enum MossVoiceLibrary {",
         "    /// App-level metadata for the built-in voices (display name, note, gender); the references live in `voices`.",
         "    public static let info: [String: (name: String, note: String, female: Bool)] = ["]
for _, vid, name, note, gender in VOICES:
    lines.append(f'        "{vid}": ("{name}", "{note}", {"true" if gender == "female" else "false"}),')
lines += ["    ]", "", "    public static let voices: [MossVoice] = ["]
for src, vid, name, note, gender in VOICES:
    lines.append(f'        MossVoice(id: "{vid}", name: "{name}", packed: [')
    for style in STYLES:
        data = json.load(open(os.path.join(work, "json", f"{src}-{style}.json")))
        codes = data["references"]["neutral"]
        lines.append(f'            "{style}": "{pack(codes)}",')
    lines.append("        ]),")
lines += ["    ]", "}", ""]
open(OUT, "w", encoding="utf-8").write("\n".join(lines))
print("wrote", os.path.abspath(OUT), os.path.getsize(OUT) // 1024, "KB")
